1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"sync"
12		"syscall"
13	)
14	
15	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
16	const (
17		StatusPending    = "pending"        // accepted, not processed for the first time yet
18		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
19		StatusSuccess    = "success"        // recorded locally and nonce consumed
20		StatusReplay     = "replay"         // nonce combination already consumed by another message
21		StatusExpired    = "expired"        // absolute expiry reached before delivery
22		StatusUnknownSrc = "unknown-source" // source chain was never registered
23	)
24	
25	// Common errors. Callers can compare with errors.Is.
26	var (
27		// ErrConflict is returned when an id is reused with different message content.
28		ErrConflict = errors.New("message id conflict: existing record has different content")
29		// ErrTerminal is returned when re-submitting a terminal id or attempting to
30		// reactivate it.
31		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
32		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
33		ErrInvalidArg = errors.New("invalid argument")
34		// ErrLocked is returned when another process holds the state directory open.
35		ErrLocked = errors.New("state directory is locked by another process")
36		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
37		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
38		// ErrStorage is returned after a storage failure; the queue must be reopened.
39		ErrStorage = errors.New("storage failure; queue must be reopened")
40	)
41	
42	// Envelope is a submitted message together with its absolute expiry time.
43	type Envelope struct {
44		Message Message
45		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
46		ExpiresAt int64
47	}
48	
49	// Record is the full persisted state of one submitted message.
50	type Record struct {
51		Msg        Envelope
52		Status     string
53		Reason     string
54		Seq        int64 // submission order, zero-based
55		Attempts   int   // number of processing attempts
56		NextRetry  int64 // 0 when not yet processed, or terminal
57		LastProcAt int64 // processing time of the most recent attempt
58	}
59	
60	// Query is the user-visible view of a Record.
61	type Query struct {
62		ID        string
63		From      string
64		To        string
65		Nonce     uint64
66		Payload   string
67		ProofAt   int64
68		ExpiresAt int64
69		Status    string
70		Reason    string
71		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
72		Attempts  int
73	}
74	
75	// Result describes what happened to one message during an Advance.
76	type Result struct {
77		ID     string `json:"id"`
78		Status string `json:"status"`
79		Reason string `json:"reason"`
80	}
81	
82	// AdvanceReport is the outcome of one Advance call.
83	type AdvanceReport struct {
84		Now     int64
85		Results []Result
86	}
87	
88	func nonceKey(from, to string, nonce uint64) string {
89		return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
90	}
91	
92	// Queue is a durable local outbox backed by a state directory. A single
93	// Queue owns the directory for writes; other processes attempting to Open the
94	// same directory fail with ErrLocked. It is safe for concurrent use by
95	// multiple goroutines, and a success record plus its nonce consumption commit
96	// as one durable unit.
97	type Queue struct {
98		mu sync.Mutex
99	
100		store  *store
101		flock  *os.File
102		broken bool // a storage write failed; all further mutations fail
103	
104		now      int64              // last advanced Unix-ms time, 0 = never advanced
105		sources  map[string]bool    // registered source chains
106		headers  map[string]Header  // latest registered header per chain
107		records  map[string]*Record // by message id
108		order    []string           // non-terminal messages, submission order
109		consumed map[string]string  // nonce combination -> successful message id
110		nextSeq  int64
111	}
112	
113	// Open opens (creating if needed) a persistent queue backed by stateDir. It
114	// takes an exclusive process lock on the directory and refuses to start when
115	// the on-disk state is corrupt or in an unsupported format, never clearing it.
116	func Open(stateDir string) (*Queue, error) {
117		if stateDir == "" {
118			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
119		}
120		if err := os.MkdirAll(stateDir, 0o755); err != nil {
121			return nil, fmt.Errorf("create state directory: %w", err)
122		}
123		abs, err := filepath.Abs(stateDir)
124		if err != nil {
125			return nil, fmt.Errorf("resolve state directory: %w", err)
126		}
127	
128		lockPath := filepath.Join(abs, "lock")
129		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
130		if err != nil {
131			return nil, fmt.Errorf("open lock file: %w", err)
132		}
133		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
134			lock.Close()
135			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
136		}
137	
138		st, state, err := openStore(abs)
139		if err != nil {
140			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
141			lock.Close()
142			return nil, err
143		}
144	
145		q := &Queue{
146			store:    st,
147			flock:    lock,
148			sources:  state.sources,
149			headers:  state.headers,
150			records:  state.records,
151			consumed: state.consumed,
152			now:      state.now,
153			nextSeq:  state.nextSeq,
154		}
155		q.order = q.reconstructOrder()
156		st.snap = q.snapshot
157		return q, nil
158	}
159	
160	// reconstructOrder returns non-terminal record ids in submission (seq) order.
161	func (q *Queue) reconstructOrder() []string {
162		seqs := make([]int64, 0, len(q.records))
163		live := map[int64]string{}
164		for id, rec := range q.records {
165			if isTerminal(rec.Status) {
166				continue
167			}
168			seqs = append(seqs, rec.Seq)
169			live[rec.Seq] = id
170		}
171		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
172		order := make([]string, 0, len(seqs))
173		for _, seq := range seqs {
174			order = append(order, live[seq])
175		}
176		return order
177	}
178	
179	// snapshot returns a detached copy of live state for log compaction. Callers
180	// must hold mu.
181	func (q *Queue) snapshot() *loadedState {
182		s := &loadedState{
183			sources:  map[string]bool{},
184			headers:  map[string]Header{},
185			records:  map[string]*Record{},
186			consumed: map[string]string{},
187			now:      q.now,
188			nextSeq:  q.nextSeq,
189		}
190		for c := range q.sources {
191			s.sources[c] = true
192		}
193		for c, h := range q.headers {
194			s.headers[c] = h
195		}
196		for id, rec := range q.records {
197			cp := *rec
198			s.records[id] = &cp
199		}
200		for k, v := range q.consumed {
201			s.consumed[k] = v
202		}
203		return s
204	}
205	
206	// Close flushes, releases the directory lock and closes the queue.
207	func (q *Queue) Close() error {
208		q.mu.Lock()
209		defer q.mu.Unlock()
210		if q.flock == nil {
211			return nil
212		}
213		var err error
214		if !q.broken {
215			err = q.store.close()
216		} else {
217			q.store.forceClose()
218		}
219		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
220		q.flock.Close()
221		q.flock = nil
222		return err
223	}
224	
225	// fail locks in a storage failure: the log tail may be partially written, so
226	// no further appends are allowed in this process (another append would turn a
227	// truncatable torn tail into unrecoverable corruption).
228	func (q *Queue) fail(op string, err error) error {
229		q.broken = true
230		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
231	}
232	
233	func (q *Queue) checkWritable() error {
234		if q.flock == nil {
235			return fmt.Errorf("%w: queue is closed", ErrStorage)
236		}
237		if q.broken {
238			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
239		}
240		return nil
241	}
242	
243	// RegisterSource records that messages may originate from chain. Idempotent.
244	func (q *Queue) RegisterSource(chain string) error {
245		if chain == "" {
246			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
247		}
248		q.mu.Lock()
249		defer q.mu.Unlock()
250		if err := q.checkWritable(); err != nil {
251			return err
252		}
253		if q.sources[chain] {
254			return nil
255		}
256		if err := q.store.appendRegisterSource(chain); err != nil {
257			return q.fail("register source", err)
258		}
259		q.sources[chain] = true
260		return q.maybeCompact()
261	}
262	
263	// UpsertHeader stores the latest known header for a chain. A header with
264	// Trusted=false records the chain tip but grants no proof coverage; a later
265	// trusted header covering the proof height can unblock waiting messages.
266	// Header updates never bypass retry scheduling and never reactivate terminal
267	// messages.
268	func (q *Queue) UpsertHeader(h Header) error {
269		if h.Chain == "" {
270			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
271		}
272		if h.Height < 0 {
273			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
274		}
275		q.mu.Lock()
276		defer q.mu.Unlock()
277		if err := q.checkWritable(); err != nil {
278			return err
279		}
280		if err := q.store.appendHeader(h); err != nil {
281			return q.fail("upsert header", err)
282		}
283		q.headers[h.Chain] = h
284		return q.maybeCompact()
285	}
286	
287	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
288	// means never expire). Re-submitting the same id with identical content
289	// returns the existing record without adding a queue entry; the same id with
290	// different content returns ErrConflict and leaves the original untouched;
291	// re-submitting a terminal id returns ErrTerminal. Success is reported only
292	// after the submission is durably persisted.
293	func (q *Queue) Submit(env Envelope) (*Record, error) {
294		m := env.Message
295		if m.ID == "" {
296			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
297		}
298		if m.From == "" || m.To == "" {
299			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
300		}
301		if m.ProofAt < 0 {
302			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
303		}
304		if env.ExpiresAt < 0 {
305			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
306		}
307	
308		q.mu.Lock()
309		defer q.mu.Unlock()
310		if err := q.checkWritable(); err != nil {
311			return nil, err
312		}
313	
314		if existing, ok := q.records[m.ID]; ok {
315			if isTerminal(existing.Status) {
316				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
317			}
318			if sameEnvelope(existing.Msg, env) {
319				out := *existing
320				return &out, nil
321			}
322			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
323		}
324	
325		rec := &Record{
326			Msg:    env,
327			Status: StatusPending,
328			Reason: "awaiting first processing",
329			Seq:    q.nextSeq,
330		}
331		if err := q.store.appendSubmit(rec); err != nil {
332			return nil, q.fail("submit", err)
333		}
334		q.records[m.ID] = rec
335		q.order = append(q.order, m.ID)
336		q.nextSeq++
337		if err := q.maybeCompact(); err != nil {
338			return nil, err
339		}
340		out := *rec
341		return &out, nil
342	}
343	
344	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
345	// be advanced repeatedly; going backwards is rejected and changes nothing.
346	//
347	// Each advance, in submission order:
348	//  1. due messages (new messages are due on the next advance; others when now
349	//     has reached their next retry time) are evaluated for replay and expiry,
350	//     replay winning on a tie and now == ExpiresAt counting as expired, then
351	//     for source registration and trusted-header coverage, and finally
352	//     delivered;
353	//  2. afterwards every remaining non-terminal message, regardless of its
354	//     retry schedule, is re-checked for replay and expiry at the new time.
355	//
356	// Unregistered sources are permanently rejected as unknown-source; registered
357	// sources without a trusted header covering the proof height stay waiting and
358	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
359	// doubling to a 60-second cap, measured from the actual processing time;
360	// jumping over several intervals still costs one attempt.
361	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
362		if nowMs < 0 {
363			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
364		}
365		q.mu.Lock()
366		defer q.mu.Unlock()
367		if err := q.checkWritable(); err != nil {
368			return nil, err
369		}
370		if q.now != 0 && nowMs < q.now {
371			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
372		}
373	
374		report := &AdvanceReport{Now: nowMs}
375	
376		// Phase 1: due messages, first-submission order.
377		for _, id := range append([]string(nil), q.order...) {
378			rec := q.records[id]
379			if rec == nil || isTerminal(rec.Status) {
380				continue
381			}
382			due := rec.Attempts == 0 || nowMs >= rec.NextRetry
383			if !due {
384				continue
385			}
386			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
387				return nil, err
388			} else if done {
389				report.Results = append(report.Results, r)
390				continue
391			}
392			r, err := q.processDue(rec, nowMs)
393			if err != nil {
394				return nil, err
395			}
396			report.Results = append(report.Results, r)
397		}
398	
399		// Phase 2: replay/expiry hold for every non-terminal message at the new
400		// time, even while its retry backoff is still running.
401		for _, id := range append([]string(nil), q.order...) {
402			rec := q.records[id]
403			if rec == nil || isTerminal(rec.Status) {
404				continue
405			}
406			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
407				return nil, err
408			} else if done {
409				report.Results = append(report.Results, r)
410			}
411		}
412	
413		if err := q.store.appendAdvance(nowMs); err != nil {
414			return nil, q.fail("advance", err)
415		}
416		q.now = nowMs
417		if err := q.maybeCompact(); err != nil {
418			return nil, err
419		}
420		return report, nil
421	}
422	
423	// maybeCompact rewrites the WAL as a snapshot once it grows past the
424	// threshold. Live state already reflects every acknowledged append, so the
425	// snapshot cannot lose records. A compaction failure is a storage failure:
426	// the queue is marked broken and must be reopened.
427	func (q *Queue) maybeCompact() error {
428		if !q.store.needsCompaction() {
429			return nil
430		}
431		if err := q.store.compact(q.snapshot()); err != nil {
432			return q.fail("compact log", err)
433		}
434		return nil
435	}
436	
437	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
438	// message or its absolute expiry has been reached. Replay wins when both
439	// hold. The bool reports whether the message was terminalized.
440	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
441		id := rec.Msg.Message.ID
442		key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
443		if winner, taken := q.consumed[key]; taken && winner != id {
444			reason := "nonce combination already consumed by message " + winner
445			if err := q.terminalize(rec, now, StatusReplay, reason); err != nil {
446				return Result{}, false, err
447			}
448			return Result{ID: id, Status: StatusReplay, Reason: reason}, true, nil
449		}
450		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
451			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
452			if err := q.terminalize(rec, now, StatusExpired, reason); err != nil {
453				return Result{}, false, err
454			}
455			return Result{ID: id, Status: StatusExpired, Reason: reason}, true, nil
456		}
457		return Result{}, false, nil
458	}
459	
460	// processDue classifies a due message against source registration and header
461	// trust, or delivers it.
462	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
463		id := rec.Msg.Message.ID
464		if !q.sources[rec.Msg.Message.From] {
465			reason := "unknown source chain " + rec.Msg.Message.From
466			if err := q.terminalize(rec, now, StatusUnknownSrc, reason); err != nil {
467				return Result{}, err
468			}
469			return Result{ID: id, Status: StatusUnknownSrc, Reason: reason}, nil
470		}
471		h, hasHeader := q.headers[rec.Msg.Message.From]
472		if !hasHeader || !h.Trusted || h.Height < rec.Msg.Message.ProofAt {
473			cur := int64(0)
474			if hasHeader {
475				cur = h.Height
476			}
477			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", rec.Msg.Message.ProofAt, cur)
478			if err := q.markWaiting(rec, now, reason); err != nil {
479				return Result{}, err
480			}
481			return Result{ID: id, Status: StatusWaiting, Reason: reason}, nil
482		}
483	
484		// Deliver: success record and nonce consumption are one log entry.
485		key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
486		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(h.Height, 10)
487		if err := q.store.appendResult(now, rec, StatusSuccess, reason, rec.Attempts+1, key, id, true); err != nil {
488			return Result{}, q.fail("deliver", err)
489		}
490		rec.Attempts++
491		rec.LastProcAt = now
492		rec.Status = StatusSuccess
493		rec.Reason = reason
494		rec.NextRetry = 0
495		q.consumed[key] = id
496		q.removeFromOrder(id)
497		return Result{ID: id, Status: StatusSuccess, Reason: reason}, nil
498	}
499	
500	func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
501		if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, "", "", false); err != nil {
502			return q.fail("terminalize", err)
503		}
504		rec.Attempts++
505		rec.LastProcAt = now
506		rec.Status = status
507		rec.Reason = reason
508		rec.NextRetry = 0
509		q.removeFromOrder(rec.Msg.Message.ID)
510		return nil
511	}
512	
513	func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
514		attempt := rec.Attempts + 1
515		if err := q.store.appendResult(now, rec, StatusWaiting, reason, attempt, "", "", false); err != nil {
516			return q.fail("schedule retry", err)
517		}
518		rec.Attempts = attempt
519		rec.LastProcAt = now
520		rec.Status = StatusWaiting
521		rec.Reason = reason
522		rec.NextRetry = now + nextRetryDelay(attempt)
523		return nil
524	}
525	
526	func (q *Queue) removeFromOrder(id string) {
527		for i, cand := range q.order {
528			if cand == id {
529				q.order = append(q.order[:i], q.order[i+1:]...)
530				return
531			}
532		}
533	}
