535	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
536	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
537	func nextRetryDelay(attempt int) int64 {
538		if attempt < 1 {
539			attempt = 1
540		}
541		if attempt > 6 {
542			return 60_000
543		}
544		return int64(1) << (attempt - 1) * 1000
545	}
546	
547	func isTerminal(status string) bool {
548		switch status {
549		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
550			return true
551		}
552		return false
553	}
