555	func sameEnvelope(a, b Envelope) bool {
556		return a.ExpiresAt == b.ExpiresAt &&
557			a.Message.ID == b.Message.ID &&
558			a.Message.From == b.Message.From &&
559			a.Message.To == b.Message.To &&
560			a.Message.Nonce == b.Message.Nonce &&
561			a.Message.Payload == b.Message.Payload &&
562			a.Message.ProofAt == b.Message.ProofAt
563	}
