565	// Query returns the current state of a message.
566	func (q *Queue) Query(id string) (Query, bool) {
567		q.mu.Lock()
568		defer q.mu.Unlock()
569		rec, ok := q.records[id]
570		if !ok {
571			return Query{}, false
572		}
573		return toQuery(rec), true
574	}
575	
576	// Queries returns all records in first-submission order.
577	func (q *Queue) Queries() []Query {
578		q.mu.Lock()
579		defer q.mu.Unlock()
580		out := make([]Query, 0, len(q.records))
581		for _, rec := range q.records {
582			out = append(out, toQuery(rec))
583		}
584		sort.Slice(out, func(i, j int) bool {
585			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
586		})
587		return out
588	}
589	
590	// Now returns the last advanced processing time, or 0 if never advanced.
591	func (q *Queue) Now() int64 {
