510	// Only one process (independent open file description) may hold the directory
511	// for writing; after the holder closes, the directory is reusable.
512	func TestProcessLock(t *testing.T) {
513		dir := t.TempDir()
514		q1, err := Open(dir)
515		if err != nil {
516			t.Fatal(err)
517		}
518		q2, err := Open(dir)
519		if !errors.Is(err, ErrLocked) {
520			if q2 != nil {
521				q2.Close()
522			}
523			t.Fatalf("second open must fail ErrLocked, got %v", err)
524		}
525		if err := q1.Close(); err != nil {
526			t.Fatal(err)
527		}
528		q3, err := Open(dir)
529		if err != nil {
530			t.Fatalf("directory must be reusable after holder exits: %v", err)
531		}
532		defer q3.Close()
533	}
