620	// A storage write failure reports a clear error and poisons the queue; after
621	// reopening, the torn unacknowledged tail is dropped and consistency holds.
622	func TestStorageFailureRecovery(t *testing.T) {
623		dir := t.TempDir()
624		q, err := Open(dir)
625		if err != nil {
626			t.Fatal(err)
627		}
