639		q2, err := Open(dir)
640		if err != nil {
641			t.Fatalf("reopen after storage failure: %v", err)
642		}
643		defer q2.Close()
644		if _, ok := q2.Query("m"); ok {
645			t.Fatalf("unacknowledged submit must not exist after recovery")
646		}
647		if !q2.sources["a"] {
648			t.Fatalf("acknowledged source registration lost")
649		}
