		switch args[i] {
		case "--state":
			if i+1 >= len(args) {
				return fmt.Errorf("--state requires a directory")
			}
			stateDir = args[i+1]
			i++
		default:
			return fmt.Errorf("unknown verify flag %q", args[i])
		}
	}
