	// historical success delivers; only the exact same triple is consumed.
	rec, err := q2.Submit(relayproof.Envelope{
		Message: relayproof.Message{ID: "q-col-2-again", From: "a", To: "b:c", Nonce: 8, ProofAt: 10},
	})
	if err != nil {
		panic(err)
	}
	_ = rec
	if _, err := q2.Advance(3000); err != nil {
		panic(err)
